# ============================================================================
# BACKEND API TESTS (cloud/rhinoCloud/tests_api, uv group api-tests)
# ============================================================================

api-test = { cmd = "uv run --frozen --group api-tests pytest tests_api -n auto --randomly-seed=1009 --junitxml=reports/junit.xml -q --tb=short", cwd = "cloud/rhinoCloud", help = "Run the whole cloud API layer in parallel. Writes reports/failures.md and reports/junit.xml. Extra args go to pytest." }

# Only the tests whose code paths changed (pytest-testmon). No -n: the set is small, and testmon + xdist must be
# checked for the pinned version first. The first run on a machine runs everything and writes .testmondata;
# the sandbox image ships one built from main. poe verify runs api-test instead when migrations or fixtures change.
api-test-affected = { cmd = "uv run --frozen --group api-tests pytest tests_api --testmon --randomly-seed=1009 -q --tb=short", cwd = "cloud/rhinoCloud", help = "Run only the API tests affected by your changes (pytest-testmon)." }
